INSERT INTO `blogs` (`Blog_Id`, `Title`, `Author`, `Description`, `Video_Link`, `Modified_Time`, `Created_Time`) VALUES
(3, 'Learn and Help: New look', 'Siva Jasthi', 'http://www.learnandhelp.com \r\n\r\nHappy to announce the launch of new look and feel for \"Learn and Help\".\r\n\r\nThanks to Lina Sadeddin (Graphic Design Professor, North Hennepin Community College) and her \"Web Design\" class students for designing the web site.  \r\n\r\nBig thanks to Elizabeth Carlson-Hamme (ICS 325, Summer 2025 @ Metro State University) for revamping the site to reflect this new design!\r\n', '', '2025-08-17 13:35:21', '2025-08-17 09:26:16'),
(4, 'Open House on 30 August 2025', 'Siva Jasthi', 'Empowering Minds, Inspiring Generosity\r\n🌐 Register: www.learnandhelp.com\r\n📅 Classes start: 6th September 2025\r\n💻 Open House: 30th August, 8:30 PM CST (31st August 7 AM IST)\r\n🔗 Zoom: https://minnstate.zoom.us/j/6512764671\r\n🆔 ID: 651 276 4671 | Passcode: 1024\r\n📧 Siva.Jasthi@gmail.com | +1 651 276 4671', NULL, '0000-00-00 00:00:00', '2025-06-12 00:00:00'),
(5, 'Student Spotlight: Amaira', 'Siva Jasthi', ' Happy to share that Amaira Srivastava from Gilbert, AZ is one the top 10 finalists for the 2025 3M Young Scientist Challenge!  Congratulations, Amaira!  That is a big accomplishment!  https://www.discoveryeducation.com/details/3m-young-scientist-challenge-announces-2025-national-finalists/\r\n\r\nI’m happy to share that she successfully completed the Python 101 course with us in May 2025. She is currently enrolled in our Summer Java course, which is in progress, and is also registered for the upcoming Data Science class starting this September. She will serve as Python 101 Teaching Assistantfor 2025-26 session.  Her journey is just beginning, and I can’t wait to see what she accomplishes next. \r\n\r\nThank you!', '', '2025-08-29 15:54:59', '2025-06-28 09:41:32'),
(10, 'Coding, Poetry, Avadhanam… and Now Pravachanam!', 'Siva Jasthi', 'Ahala, our Teaching Assistant for the Python DL class, delivered her first public Pravachanam (spiritual discourse) on the occasion of the Ganesh Chaturthi festival at Lansem Etania Complex, Hyderabad, on 08/28/25.\r\n\r\nAs many of you know, she is the author of several metered poetry books (Telugu Satakalu), the co-author of the SHEROES book, and has successfully performed four Avadhanams so far.\r\n\r\nYou can read more about her accomplishments here: https://www.projectabcd.com/about.php\r\n\r\nCongratulations, Ahala! We are truly proud of you.', 'https://www.youtube.com/watch?v=1OXMnb-f3iw', '2025-08-28 09:10:07', '2025-08-28 09:10:07'),
(12, 'Building Futures Through School Libraries', 'Siva Jasthi', 'Over the last few years, Learn and Help, in partnership with other non-profits, has set up around 150 school libraries in Andhra Pradesh and Telangana. Many of these libraries were established in schools nominated by our community members.\r\n\r\nWe know how much a library can mean to a child—a doorway to curiosity, confidence, and lifelong learning. \r\n\r\nLooking ahead, the Learn and Help program is planning to support around 125 schools before December 2025.\r\n\r\nWe already have a strong pipeline of schools lined up, but there is still room for more nominations. If you know of a deserving school—especially one with a dedicated teacher who can administer the library—please take a few minutes to nominate it (Help--> Nominate a School). You are welcome to submit multiple nominations.\r\n\r\nJoin Us in Making a Difference\r\n\r\nEvery library we set up is a step toward empowering children with knowledge, creativity, and hope. Together, we can continue to expand the reach of education and generosity.\r\n\r\nThank you for being an essential part of the \"Learn and Help\" journey.\r\n\r\nWarm regards,\r\nSiva Jasthi, Ph.D.\r\nChief Instructor\r\nwww.learnandhelp.com', '', '2025-09-02 10:41:01', '2025-09-01 20:57:55'),
(13, 'Celebrating our TA: James Ren Wins Bronze at Junior Fencing Championships!', 'Siva Jasthi', 'We are thrilled to share some exciting news about one of our own—James Ren, Teaching Assistant for Python ML at Learn and Help.\r\n\r\nIn February 2025, James showcased not only his dedication to academics but also his athletic excellence by winning the Bronze Medal (3rd place) at the Junior Fencing Championships. Competing against some of the most talented young fencers in the nation, James demonstrated grit, focus, and determination—qualities that shine through in both his fencing and teaching.\r\n\r\nAt Learn and Help, he supports our middle and high school students in mastering advanced Python concepts and applying them to real-world data science projects.\r\n\r\nCongratulations, James, on this incredible achievement!', 'https://www.youtube.com/watch?v=F4_Nd510xdk', '2025-09-09 18:57:40', '2025-09-09 18:57:40'),
(14, 'NCWIT Aspirations in Computing (AiC) Award Applications Open!', 'Siva Jasthi', 'Dear Parents and Students,\r\n\r\nWe are excited to share that the applications for the NCWIT Aspirations in Computing (AiC) Award are now open!\r\n\r\nThis is a wonderful opportunity for high school girls (grades 9–12) from the Learn and Help program to gain recognition for their passion, talent, and aspirations in technology and computing.\r\n\r\nApplication Deadline: October 28, 2025\r\n\r\nHow to Apply?  Visit ncwit.org  or Go directly to the application portal: https://www.aspirations.org/award-programs/apply-for-an-award\r\n\r\nWe highly encourage eligible students to apply. This award not only provides recognition but also connects students with mentors, scholarships, internships, and a supportive community of peers in computing.\r\n\r\nIf you have any questions or need guidance with the application, please don’t hesitate to message me.\r\n\r\nThanks,\r\nSiva Jasthi\r\n+1 651 276 4671', '', '2025-09-12 18:56:39', '2025-09-12 18:54:12'),
(15, 'Preparing Our Students for the Age of AI', 'Siva Jasthi', 'Dear Parents and Students,\r\n\r\nToday at Learn and Help, I introduced an AI LLM (Large Language Model) tool to our Python DS and Python ML students. We will soon be extending this to our Python 101 class as well.\r\n\r\nAI is reshaping how we learn and work, and our responsibility is to ensure that students become masters of these tools, not dependents—just as one must understand math before relying on a calculator. When applied wisely, AI can empower learners to achieve more and explore deeper.\r\n\r\nIf you notice your child finishing work faster and becoming more productive, it may be thanks to this new exposure. Please know that we have checks and balances in place to make sure their learning is genuine and meaningful.\r\n\r\nTips for Parents: Here are three simple ways you can help your child become a confident master of AI tools:\r\n\r\n* Encourage independence: Ask them to first try solving problems on their own.\r\n\r\n* Promote understanding: Have them explain their solutions in their own words.\r\n\r\n* Foster curiosity: Inspire them to use AI to explore new ideas—not just to complete tasks.\r\n\r\nTogether, we can help our students thrive in this rapidly changing world.\r\n\r\nWarm regards,\r\nSiva Jasthi, Ph.D.\r\nwww.learnandhelp.com', '', '2025-09-13 11:52:19', '2025-09-13 11:45:20'),
(16, 'From Python 101 to Portfolio: Getting Started on GitHub', 'Siva Jasthi', 'Dear Parents,\r\n\r\nWe are excited to welcome 27 new students to the Learn and Help family through our Python 101 course! Most of them are middle school students, and we are also glad to have a couple of adult learners joining us.\r\n\r\nI envision that many of these students will continue their journey with Learn and Help, taking several courses over the coming years—such as Python for Data Science, Python for Machine Learning, Java 101, and Web Application Development.\r\n\r\nBy the time they enter high school, our goal is for each student to have built a portfolio of projects that they can showcase for academic and career opportunities. The best place to host and share such work is GitHub\r\n.\r\n\r\nIn addition, we are working on developing digital assets for learning computational thinking and programming. In the future, these will be available and accessible only through GitHub.\r\n\r\n???? Therefore, I strongly recommend that every student create a GitHub account at www.github.com\r\n.\r\nWe kindly request parents to either create an account for their children or guide them in doing so.\r\n\r\nThank you for your continued support in helping our students grow in their learning journey.\r\n\r\nWarm regards,\r\nLearn and Help', '', '2025-09-14 17:11:12', '2025-09-14 17:11:12'),
(17, 'Power to the youth: How a Minnetonka High School student is representing young Minnesotans ', 'News from Sun Sailor', 'From Sun Sailor (Sep 15, 2025) \r\nBy Natalie Trimble, [natalie.trimble@apgecm.com] \r\n   \r\nCongressional District 6 youth representative Samhita Krishnamurthy.\r\n\r\n\r\nMinnetonka High School student Samhita Krishnamurthy has been appointed one of four representatives from Congressional District 6 in the 2025–26 Minnesota Youth Council.\r\n\r\nShe will be among the 36 youth representatives from middle schools and high schools across the state. The goal of the program is to amplify the voice and power of young people, according to mnyouth.net. The Minnesota Youth Council was established by state statute in 2013 and is the official statewide voice for young generations.\r\n\r\nIn this official role, Krishnamurthy and her fellow representatives will advise Gov. Tim Walz and state legislators on matters pertaining to Minnesota’s youth. The Youth Council will be responsible for selecting introduced bills to be considered for public hearing, proposing youth legislation, preparing a youth omnibus bill and giving legislators opinions on bills from a young person’s perspective.\r\n\r\nIts core values include ensuring all young people have a voice in their communities, building authentic interpersonal relationships, involving youth in community service opportunities focused on results and providing youth with access to important resources.\r\n\r\nKrishnamurthy’s involvement in her school’s speech and debate team for the last four years is what originally sparked her interest in public speaking and advocacy, particularly when it relates to uplifting youth voices.\r\n\r\nThrough her extracurricular activities, the sophomore became increasingly knowledgeable on topics such as lobbying on congressional bills and speaking up about pressing societal issues, inspiring her to become more hands-on with the state’s policymaking procedures.\r\n\r\nAfter doing her own research on ways to become more involved in her community, she discovered the Minnesota Youth Council opportunity.\r\n\r\n“There are so many bills out there that affect the youth, but youth don’t know how to shape that. So I really wanted to be part of that process,” Krishnamurthy said. “I’m not just educating the youth, but also acting as a liaison between the government and the youth community.”\r\n\r\nThe application and interview processes are quite competitive, given the limited number of seats available on the Council. Interested students first fill out an application and if they are chosen for the next step, they complete their first round of interviews. Finalists then complete a second round of interviews prior to finding out if they will be offered a position on the Council.\r\n\r\nKrishnamurthy was appointed to her position last spring. She described the moment she found out she was chosen to represent the youth as a “dream come true.”\r\n\r\n\r\nThis past summer, the Council was invited to attend a retreat together to establish which topics would be of high priority this upcoming year. The 36 youth representatives met with Lt. Gov. Peggy Flanagan and members from the Minnesota Alliance With Youth to gain a better understanding of what areas they should focus their attention towards.\r\n\r\nA few significant topics include increasing the involvement of student voices at school board meetings, providing youth with access to substance prevention resources and creating healthier and more inclusive school environments for students.\r\n\r\nTo ensure the inclusion and consideration of youth voices in governmental environments, each youth representative will be required to reach out to at least 20 youth per month to survey them and gain accurate insight into the needs of Minnesota youth. “We really do value that direct engagement, so we’re able to better represent the youth voices in our communities,” Krishnamurthy said.\r\n\r\n\r\nShe’s looking forward to the new opportunities and skills that she will gain through her experience with the Minnesota Youth Council and explained that she has already learned so much from her fellow youth representatives.\r\n\r\nVisit mnyouth.net for more information.\r\n\r\nTags: Minnesota Youth Council | Minnetonka High School | Lieutenant Governor | Peggy Flanagan | Youth Representative | Samhita Krishnamurthy | www.mnyouth.net\r\n | Minnesota Alliance\r\n\r\nBy Natalie Trimble, [natalie.trimble@apgecm.com] ', '', '2025-09-15 14:01:31', '2025-09-15 13:59:11'),
(18, 'Celebrating Manchi Pustakam: TALHero™ Awardee of 2025', 'Siva Jasthi', 'Kindness is humanity’s greatest strength, and this year’s TALHeroes 2025 prove it again! We are thrilled that our partner Manchi Pustakam has been honored as a TALHero™ Awardee of 2025 in the Nonprofit category.  See this year’s impactful stories here: https://touchalife.org/talhero-awards-2025/\r\n\r\nFor over two decades, Manchi Pustakam has nurtured a love for reading among children in Telangana and Andhra Pradesh. With 500+ titles and 200,000+ books distributed annually across 400+ schools, it has become a beacon for storytelling, equality, and imagination.\r\n\r\nAt Learn and Help, we’ve proudly partnered with Manchi Pustakam for the past three years to set up school libraries in India. This recognition celebrates not only their inspiring journey but also the grassroots reading culture we are building together.\r\n\r\nCongratulations to the entire Manchi Pustakam team for this well-deserved honor. We are proud to stand by your side in empowering young minds and spreading the joy of books.', '', '2025-10-03 08:01:11', '2025-10-03 08:01:11'),
(19, 'Celebrating Amaira Srivastava — Our Learn and Help Star and Top 3M Young Scientist!', 'Siva Jasthi', 'Dear All,\r\n\r\nWe are thrilled to share some exciting news about our very own Teaching Assistant for Python 101 @ Learn and Help — Amaira Srivastava!\r\n\r\nAmaira has been recognized as one of the Top 10 finalists in the 2025 3M Young Scientist Challenge — a remarkable national competition celebrating innovation, creativity, and scientific excellence.\r\n\r\nLast week, Amaira and her parents visited 3M headquarters in Minneapolis, where she met with scientists and other finalists to present her project — “FlavoPeel Cup.” We are proud to announce that Amaira’s project earned 2nd place nationwide, along with a $1,000 cash prize!\r\n\r\nYou can learn more about her innovative project here:\r\nFlavoPeel Cup – in Amaira’s words  https://www.youtube.com/watch?v=a5-Mx3IoOcQ\r\n\r\nThe Top 3 finishers were also invited to the New York Stock Exchange (NYSE) to ring the opening bell — a once-in-a-lifetime experience! Amaira proudly represented the Learn and Help community when she rang the bell on October 20, 2025.\r\n\r\nI had the pleasure of meeting Amaira and her parents over dinner during their visit to Minneapolis. It was inspiring to hear about her journey, passion for science, and dedication to learning. I am confident Amaira will achieve many more milestones ahead — and we can’t wait to see her grow into a Lead Instructor at Learn and Help.\r\n\r\nCongratulations, Amaira! You continue to make us proud and inspire your fellow students. ????\r\n\r\nBelow are some links and media highlights featuring Amaira and other 3M Young Scientist finalists:\r\n\r\n1️⃣ FlavoPeel Cup – Amaira’s Project\r\nhttps://youngscientistlab.com/annual-challenge/finalists-mentors-judges/finalists/amaira-srivastava-2025-finalist\r\n\r\n2️⃣ Meet the 2025 3M Young Scientists\r\nhttps://news.3m.com/Meet-the-2025-3M-Young-Scientist-Challenge-finalists-who-are-reimagining-whats-possible\r\n\r\n3️⃣ FOX 10 Phoenix – Amaira’s Story\r\nhttps://www.fox10phoenix.com/news/arizona-teen-named-top-young-scientist-finalist\r\n\r\n\r\n4️⃣ CBS Minnesota News – 3M Challenge Finalists\r\nhttps://www.cbsnews.com/minnesota/news/3m-young-scientists-challenge-finalist-presentations-st-paul/\r\n\r\n5️⃣ 3M News Release\r\nhttps://news.3m.com/2025-10-15-13-year-old-from-California-named-Americas-Top-Young-Scientist-for-inventing-innovative-fall-detection-home-safety-system\r\n\r\n\r\n6️⃣ 3M Young Scientists at NYSE – Instagram Reel\r\nhttps://www.instagram.com/reel/DQC4EmniThV/\r\n\r\nAnd here are a few photos capturing Amaira’s memorable moments — from the 3M event to the NYSE bell ringing ceremony.', 'https://www.youtube.com/watch?v=a5-Mx3IoOcQ', '2025-10-21 19:59:27', '2025-10-21 19:50:59'),
(20, 'Celebrating Samhita — TWIST 2025 EPIC Award Winner!', 'Siva Jasthi', 'I’m thrilled to share that one of our students, Samhita Krishnamurthy from Minnetonka High School, has been honored with the TWIST (Target Women in Science and Technology) 2025 EPIC Award!\r\n\r\nThe TWIST EPIC Awards recognize young women who demonstrate Excellence, Passion, Innovation, and Courage in technology and leadership. It’s truly inspiring to see Target’s initiative uplifting the next generation of women in STEM — and I couldn’t be prouder that Samhita is among this year’s winners.\r\n\r\nSamhita joined Learn and Help program with curiosity and a genuine love for learning. She completed Python 101, Python 102, and Java programming courses, mastering not only the technical side of coding but also developing a deeper appreciation for problem-solving and computational thinking. She also earned PCEP (Python Certified Entry-Level Programmer) Certification.\r\n\r\nAt Minnetonka High School, Samhita founded the school’s Girls Who Code chapter, creating a space where young women could explore computing together. She’s also an active member of NCWIT (National Center for Women & Information Technology) and was recognized as a Rising Star Award Recipient for her contributions.\r\n\r\nThrough DECA Business Operations Research, Samhita designed an innovative HAIR Framework — a project that showcases how AI and AR can improve operational efficiency for small businesses. Her work beautifully blends technology and creativity, showing how computing can drive real-world impact.\r\n\r\nSamhita’s story captures the very essence of Learn and Help — learning deeply, helping others, and using knowledge to make a difference. Her success is a reminder of why I started this program: to spark curiosity, build confidence, and inspire students to use their talents for good.\r\n\r\nCongratulations, Samhita — your journey has just begun, and I can’t wait to see all the ways you’ll continue to shine in the world of technology!\r\n', '', '2025-10-27 21:24:30', '2025-10-27 21:24:30'),
(21, 'Exciting News: Learn and Help is Now Officially a Registered Nonprofit!', 'Siva Jasthi', 'Empowering Minds, Inspiring Generosity!\r\n\r\nWe are thrilled to share a major milestone in our journey — Learn and Help is now officially registered as a nonprofit organization in the state of Minnesota!\r\n\r\nWe’ve received our Minnesota File Number, State Tax ID, and Federal EIN from the IRS. Our application for 501(c)(3) tax-exempt status is currently under review, and we expect formal approval within the next 3 to 4 weeks.\r\n\r\nThis marks an important step toward expanding our mission — Empowering Minds, Inspiring Generosity — by creating more opportunities for students to learn meaningful skills and give back to their communities.\r\n\r\nA heartfelt thank you to all parents, students, community members, and our board for your continuous support, encouragement, and trust. Your belief in our vision keeps us moving forward every day.\r\n\r\nStay tuned for more updates as we continue to grow our programs, launch new learning initiatives, and make an even greater impact together!\r\n\r\nWith gratitude,\r\nSiva Jasthi\r\nFounder, Learn and Help\r\nwww.learnandhelp.com', '', '2025-10-31 16:52:32', '2025-10-31 16:52:32'),
(22, 'Learn and Help is Now a 501(c)(3) Nonprofit ????', 'Siva Jasthi', 'Dear Learn and Help Community,\r\n\r\nWe are delighted to share an important milestone in our journey.\r\n\r\nLearn and Help has officially been granted 501(c)(3) nonprofit status by the U.S. Internal Revenue Service. This recognition affirms our mission and allows us to expand our impact even further.\r\n\r\nWhat this means for our community:\r\n\r\n* Donations to Learn and Help are now tax-deductible as permitted by law\r\n* We can partner more effectively with schools, educators, donors, and institutions\r\n* Every contribution directly supports our mission of empowering students through learning and generosity\r\n\r\nOur EIN: 39-5158217\r\n\r\n\r\nThis achievement belongs to all of you — our students, parents, teachers, volunteers, donors, and well-wishers. \r\n\r\nThank you for believing in the idea that learning and helping can go hand in hand.\r\n\r\nWith gratitude,\r\nSiva Jasthi\r\nFounder, Learn and Help', '', '2026-01-27 15:23:29', '2026-01-27 15:23:29');
