(6, 'Vunnava Dot Com', 'community_center', 'vunnava.jpg', 'https://www.vunnava.com', 'Contributed to the Burial Ground development project in Vunnava village, Guntur District, India', 'approved', '2025-08-27 23:31:32', '2025-08-31 02:46:49'),
(7, 'Silicondhra Manabadi', 'school', 'manabadi_logo.png', 'https://manabadi.siliconandhra.org/', 'Provided classroom supplies to Manabadi teachers through contributions from our students', 'proposed', '2025-08-27 23:31:32', '2025-08-28 03:30:01'),
