(10, 'Math and Science Academy, Woodbury, MN', 'school', 'school_math_and_science_academy.png', 'https://www.mnmsa.org/', 'Supported the classrooms nominated by our students', 'proposed', '2025-08-28 00:22:32', '2025-08-28 00:22:32'),
(11, 'Westwood High School Robotics, Austin, TX', 'school', 'school_westwood_highschool.png', 'https://westwoodrobots.org/', 'Supported the Robotics team at Westwood High School', 'proposed', '2025-08-28 00:32:01', '2025-08-28 00:32:01'),
(12, 'Parkways Schools Chesterfield, MO', 'school', 'schools_parkways_MO_20250827_190428.png', 'https://www.parkwayschools.net', 'Supported the classrooms nominated by our students', 'proposed', '2025-08-28 01:04:28', '2025-08-28 01:04:28'),
(13, 'DELETE THIS ENTRY', 'library', 'nova_20251009_141043.jpg', 'http://www.nova.com', 'This is an entry', 'proposed', '2025-10-09 20:10:43', '2025-10-09 20:10:43');
INSERT INTO `events` (`id`, `title`, `date`, `start_time`, `end_time`, `presenter`, `description`, `event_image`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Learn and Help : Open House (2025-26)', '2025-08-30', '20:30:00', '21:30:00', 'Siva Jasthi', 'Have questions about Learn and Help?\r\nCurious about the classes we’re offering this year?\r\nDo you have a middle schooler or high schooler interested in learning programming?\r\nWant to participate in our mission of Empowering Minds, Inspiring Generosity?\r\nInterested in knowing how our students learn?\r\nWant to know how our students support different causes?\r\n\r\nJoin our Open House on Zoom with founder Siva Jasthi to know about our mission.\r\n\r\n\r\n* Open House: 30th August, 8:30 PM CST (31st August 7 AM IST)\r\n* Zoom: https://minnstate.zoom.us/j/6512764671\r\n* ID: 651 276 4671 | Passcode: 1024\r\n', 'web_dev_intro.jpg', 'completed', '2025-08-29 05:02:38', '2025-08-31 14:12:26'),
(2, 'Starting and Sustaining a Non-Profit', '2025-10-25', '20:00:00', '21:00:00', 'Ram Gada', 'Learn and Help: Empowering Minds, Inspiring Generosity\r\n\r\nAs part of our new series of expert sessions, I am delighted to announce a very special presentation:\r\n\r\n“Starting and Sustaining a Non-Profit”\r\nSpeaker: Ram Gada – Founder and Board Member of several non-profits in Minnesota\r\nDate & Time: Saturday, October 25th at 8:00 PM CST\r\n\r\n* Zoom: https://minnstate.zoom.us/j/6512764671\r\n* ID: 651 276 4671 | Passcode: 1024\r\n\r\n\r\nSome of our high school students have expressed interest in starting a non-profit, and I am also working on formally establishing Learn and Help as a non-profit organization. To guide us on this journey, Ram Gada ji has graciously agreed to share his experiences, practical guidelines, and wisdom.\r\n\r\nThis is a wonderful opportunity to:\r\n\r\n* Learn what it takes to build and grow a non-profit\r\n* Gain inspiration from someone with decades of community service\r\n* Explore how young people can create a legacy of impact\r\n\r\nPlease bring your ideas, aspirations, and questions. Together, we will learn from Rama Gada’s journey and insights.\r\n\r\nThis session is open to everyone – current students, alumni, parents, and anyone interested in learning more about non-profits.', 'database_workshop.png', 'scheduled', '2025-08-29 05:02:38', '2025-10-17 15:41:17'),
(3, 'First Day of Classes for 2025-26 Session', '2025-09-06', '09:00:00', '11:00:00', 'Siva Jasthi', 'First Day of Classes for 2025-26 Session\r\n\r\nPython 101-M: 7th September (9 to 10:30 AM CST)\r\nPython 101-E: 7th September (7 to 8:30 PM CST)\r\nPython ML: 6th September (9 to 10 AM CST)\r\nPython DS: 6th September (10 to 11 AM CST)\r\n', 'react_masterclass.jpg', 'completed', '2025-08-29 05:02:38', '2025-09-11 01:57:16'),
(4, 'Unlocking Opportunities: Competitions, Certifications, and Awards for Your College Journey', '2025-10-17', '20:00:00', '21:00:00', 'Ishana Didwania', 'Join Ishana Didwania, former Learn and Help Teaching Assistant and now the Director of Student Achievement, as she shares her inspiring journey from Learn and Help to Purdue University and beyond. In this session, Ishana will guide students on how to pursue coding and data science competitions, earn certifications, participate in hackathons, and apply for awards. She will also explain how these opportunities can strengthen your skills, expand your network, and enhance your college applications and career prospects.\r\n\r\nBlock your calendar for for an hour at Friday 17th October 2025 @ 8 PM CST. \r\n\r\nHow to join the event?  https://minnstate.zoom.us/j/6512764671\r\n\r\nMeeting ID: 651 276 4671\r\nPasscode: 1024', 'event_4_1760465543.png', 'completed', '2025-09-02 21:31:04', '2025-10-18 04:21:05'),
(5, 'Minnesota 529 College Savings Plan', '2025-09-23', '12:00:00', '13:00:00', 'mnsaves.org', 'MNSAVES makes it easier to save for higher education\r\nwith triple tax benefits. Not only are Minnesota taxpayers\r\neligible for a state income tax deduction, any earnings in a\r\nMNSAVES account grow tax-deferred, and withdrawals are\r\n100% tax free when used for qualified higher education\r\nexpenses.\r\n\r\nHere is the link to register for the seminar https://event.on24.com/wcc/r/5051750/F7C63E382B39743CDB94204706F72AEE', 'event_1758055707_68c9cd1b081fc.png', 'completed', '2025-09-16 20:48:27', '2025-09-29 02:57:58'),
(6, 'Health Event Discussion with Dr. Sarada', '2025-11-02', '10:00:00', '11:00:00', 'Dr. Sarada', 'event describption', 'event_1762055230_6906d43ec422c.png', 'scheduled', '2025-11-02 03:47:10', '2025-11-02 03:47:10');
INSERT INTO `instructor` (`instructor_ID`, `First_name`, `Last_name`, `Bio_data`, `Image`) VALUES
(1, 'Siva ', 'Jasthi, Ph.D.', 'Founder, President, and Chief Instructor\r\n\r\nDr. Siva Jasthi is a software consultant, educator, and author based in Minneapolis. With a Ph.D. in Mechanical Engineering from IIT Delhi and 28+ years in the software industry, he also serves as adjunct faculty at Metropolitan State University. Beyond his career, he has led community initiatives such as founding Vunnava Dot Com to support his native village, creating 10,000+ Telugu puzzles, and developing cultural projects like Project ABCD and the book SHEROES. In 2021, he started Learn and Help, a program teaching programming to students while funding school libraries in India. He has authored several books blending education, culture, and storytelling.', 'images/instructors/siva.png'),
(2, 'Amaira', 'Srivatsava', 'Teaching Assistant (Python 101) (2025-26)\r\n\r\nAmaira Srivastava is a passionate and well rounded student leader currently attending ACP High School in Arizona as a freshman. She has completed Python 101 and AP Computer Science A (Java) through the Learn and Help Program under Dr. Siva Jasthi. A top ten finalist in the 2025 3M Young Scientist Challenge, she is also a Thermo Fisher Scientific Junior Innovators Challenge nominee, and a First Prize winner at the Arizona State Science & Engineering Fair.\r\n\r\nAn accomplished communicator, Amaira was a National Speech & Debate Octofinalist 2025. She has served as both Student Council President and Chief Science Officer, leading school-wide initiatives and STEM outreach programs in her community. Dedicated to service, she volunteers with Knight Buddies, offering academic and emotional support to underserved students.\r\n\r\nOutside the classroom, Amaira is a National Junior Honor Society (NJHS) Scholar, a black belt in Taekwondo, a competitive table tennis player, and an artist.', 'images/instructors/instructor_689b622e422bf0.40783962.png'),
(4, 'Ahala', 'Ayyalasomayajula', 'Teaching Assistant (Python DS) (2025-26) \r\n\r\nAhala Ayyalasomayajula, an eighth grader at Future Kids School, Hyderabad, is an avid reader, poet, and young programmer. She is the author of Ahala MaTa (2021) and Padmavathi Priya Satakam (2022) and is recognized as the youngest Avadhani, having completed her first Ashta Avadhanam in 2022. Ahala was also the first student in the Learn and Help program to earn the Python Entry Level Certified Programmer (PCEP) certification and is now advancing her programming skills with Dr. Siva Jasthi. She will serve as a Teaching Assistant for the Python for Data Science course in 2025–26. Alongside academics, she enjoys table tennis, badminton, art, biking, and running with her family.', 'uploads/ahala_2025.png'),
(8, 'James', 'Ren', 'Teaching Assistant (Python ML) (2025-26) \r\nJames Ren is a junior at the Johns Hopkins Center for Talented Youth High School with a strong academic focus in computer science and STEM.\r\nHe is proficient in Python and Java, with foundational knowledge of HTML, CSS, and JavaScript. James has successfully completed AP Computer Science A, AP Computer Science Principles, and several other STEM-related AP courses.\r\nHe earned both the Certified Entry-Level Python Programmer (PCEP) and the Certified Associate Python Programmer (PCAP) certifications. He was also selected to join the Pathways in Data Science program hosted by the University of Chicago.\r\nBeyond academics, James is a top nationally ranked fencer and has represented Team USA in international competitions.', 'images/instructors/instructor_68a681c6b10dc5.68332676.jpeg'),
(101, 'Ishana ', 'Didwania', 'Former Teaching Assistant (Python 101)\r\n\r\nIshana Didwania is a sophomore at Purdue University majoring in Computer Science. She is currently a Machine Learning intern at Humana, where she is developing an AI knowledge-surfacing voice agent for home health clinicians. At Purdue, she is engaged in Generative AI research focused on creating an autonomous data exploration agent, and she fundraises for the Riley Hospital for Children through Purdue University Dance Marathon.\r\n\r\nIshana has been deeply involved with Learn and Help for several years. She served as a Teaching Assistant for Python 101 for two years, supporting students in their programming journey and building meaningful one-on-one connections. Her passion for teaching and mentoring has made a lasting impact on the program and its students.\r\n\r\nHer background in computer science education began at the School of India for Languages and Culture (SILC), where she completed a five-year Computer Science program covering HTML, CSS, JavaScript, PHP, MySQL, Python, and Java. She later served as the primary HTML and CSS instructor for three years, dedicating over 75 hours annually to teaching 6th-grade students.\r\n\r\nBeyond her teaching contributions, Ishana is a software engineer and the head of strategy for DiaBuddies, a Technovation team app designed to support diabetic children. She developed the app’s health tracker feature and authored its business plan, which was recognized by U.S. Bank and presented to its executive board.', 'images/instructors/Ishana.png'),
(102, 'Sumedh ', 'Ghatti ', 'Former Teaching Assistant (Python 101)\r\n\r\nWith extensive expertise as an app. game developer and website developer,\r\nSumedh Ghatti\'s passion for coding ignited during his early years at the School of India for Languages and Culture (SILC).\" He earned two Python certifications in April 2023. He has also been selected to join the Deep-Dive Al workshop hosted by the University of Texas at Dallas. Beyond his academic and athletic, he expresses himself artistically through playing the tabla. In his role as an educator, Sumedh strives to ignite curiosity, foster a pursuit of excellence, and guide students in discovering their passion for coding, mirroring his own journey. He is also an excellent tennis player distinguished by the prestigious Presidential Award', 'images/instructors/sumedh.png'),
(103, 'Deepta', 'Jasthi', 'Former Teaching Assistant (Python DS)\r\n\r\nDeepta Jasthi is an Analyst at Magna Technology Group and a former teaching assistant for the Learn and Help program. She graduated from UC Berkeley in May 2024 with a double major in Data Science and Business. During her studies, she gained diverse industry experience through internships in data science, revenue operations, product strategy, and business analysis at organizations including Amplitude, Ava Community Energy, First Republic Bank, and Land O’Lakes. Deepta has strong skills in Python, machine learning, data visualization, and Salesforce, and has also contributed as a consultant with Teachers Without Borders. Outside of work, she enjoys music and is an accomplished pianist.', 'images/instructors/deepta_pic.png'),
(104, 'Mayukha', 'Ivaturi', 'Mentor for Python 101 and Python DS Classes\r\nMayukha Ivaturi, a ninth grader at Rushing Middle School in Dallas, began her tech journey in 2022 with Learn and Help’s Python 101 course, which ignited her passion for computer science. Since then, she has completed Python 102 and Python Data Science and is now pursuing Python Machine Learning (2025–26).\r\nIn 2023, she earned the PCEP (Python Certified Entry-Level Programmer) certification, showcasing her strong programming foundation. Her projects — including a credit card validator, gas price analyzer, and SHEROES-inspired alphabet index — reflect her creativity and problem-solving skills.\r\nMayukha’s Data Science work includes web scraping, REST APIs, and visualizing real-world data using Pandas, NumPy, Matplotlib, and Seaborn, highlighted by her YouTube trends analysis project. She also contributed her artistic talent to the SHEROES audiobook, designing animations that bring inspiring stories to life.\r\nBeyond coding, Mayukha volunteers with the SiliconAndhra Manabadi program, promoting Telugu language and culture.', 'images/instructors/mayukha.png');
