INSERT INTO `recommended_orgs` (`org_id`, `suggester_id`, `org_name`, `cause_category`, `description`, `website_url`, `org_email`, `status`, `address`, `created_at`, `updated_at`, `notes`) VALUES
(1, 86, 'Telugu Association of MN', 'Arts & Culture', 'Preserve and perpetuate the cultural heritage of Telugu speaking people of Greater Minnesota. Assist and promote cultural, charitable, educational, social and community affairs of the Telugu speaking people in Greater Minnesota. Foster harmony within the Telugu community and to share our diverse culture with the Greater Minnesota community.', 'http://www.telugumn.org/', 'team@telugumn.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(2, 86, 'Minnesota Area Telangana Association', 'Arts & Culture', 'The Minnesota Area Telangana Association was committed to preserve and celebrate Telangana’s unique cultural identity within the broader Telugu community.', 'https://www.telanganamn.org/', 'president@telanganamn.org', 'pending', NULL, NULL, NULL, NULL),
(3, 86, 'India Association of Minnesota', 'Arts & Culture', 'A non-profit organization serving since 1973 to build a strong and cohesive community of over 50,000 Asian Indians in Minnesota. Through Culture, Charity and Connections, IAM builds bridges of understanding between Asian Indians and society at large.', 'https://iamn.org/', 'info@iamn.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(4, 86, 'Indian Cultural Association of Minnesota', 'Arts & Culture', 'Promotes Indian cultural activities and provides opportunities for individuals and groups to get involved and make a difference in the community they serve.', 'https://icamn.org/', 'info@icamn.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(5, 86, 'Minnesota Bengali Association', 'Arts & Culture', 'Preserves and promotes Bengali culture, language, and traditions within the Minnesota Bengali community through cultural events and educational programs.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(6, 86, 'Minnesota Gujarati Samaj', 'Arts & Culture', 'Serves the Gujarati community in Minnesota by organizing cultural events, festivals, and community gatherings to preserve Gujarati heritage and traditions.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(7, 86, 'Minnesota Tamil Sangam', 'Arts & Culture', 'Dedicated to preserving Tamil culture, language, and arts in Minnesota through cultural programs, language classes, and community events.', 'http://tamilsangam.com', '', 'pending', '', '2025-08-30', '2025-10-06', ''),
(8, 86, 'Minnesota Malayalee Association', 'Arts & Culture', 'Promotes Malayalam language and Kerala culture in Minnesota through festivals, cultural programs, and community service activities.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(9, 86, 'Minnesota Kannada Koota', 'Arts & Culture', 'Serves the Kannada-speaking community in Minnesota by organizing cultural events and promoting Kannada language and Karnataka traditions.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(10, 86, 'Bharatiya Temple of Minnesota', 'Arts & Culture', 'Hindu temple and cultural center serving the spiritual and cultural needs of the Indian community in Minnesota with religious services and cultural programs.', 'https://bharatiyatemple.org/', 'info@bharatiyatemple.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(11, 86, 'Sikh Society of Minnesota', 'Arts & Culture', 'Serves the Sikh community in Minnesota through religious services, cultural programs, and community outreach activities.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(12, 86, 'Minnesota India Business Association', 'Community Development', 'Promotes business networking and economic development opportunities for Indian-American professionals and entrepreneurs in Minnesota.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(13, 86, 'Ragamala Dance Company', 'Arts & Culture', 'Internationally renowned dance company rooted in South Indian Bharatanatyam dance form, manifesting a relationship between ancient and contemporary. Led by acclaimed artists and offering classical training in Bharatanatyam.', 'https://www.ragamaladance.org/', 'info@ragamaladance.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(14, 86, 'Kala Vandanam', 'Arts & Culture', 'Indian dance school focused on building confidence in children and helping them share their cultural heritage through dance. Dedicated to preserving Indian classical dance traditions while making them accessible to young learners.', 'https://kalavandanam.com/', 'info@kalavandanam.com', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(15, 86, 'Natyakala Dance Academy', 'Education', 'Founded by Sona Nair, teaches classical Indian dance forms including Bharatanatyam, Mohiniyattam, and Kuchipudi. Focuses on traditional training and cultural education for students of all ages.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(16, 86, 'Archana Nrityalaya - Kathak Dance Academy', 'Arts & Culture', 'Founded by Guru Asha Joglekar in 1963, specializes in Kathak classical dance training. Known for exceptional teaching skills, personal attention, and in-depth knowledge of Kathak traditions.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(17, 86, 'Arya Dance Academy', 'Education', 'Platform for current and prospective generations to immerse themselves in classical Indian dance forms. Offers training in various styles with focus on rich cultural heritage and artistic development.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(18, 86, 'Bollywood Dance Minnesota', 'Arts & Culture', 'Offers Bollywood dance classes for children ages 5-10 and adults. Provides fun and energetic dance instruction combining traditional Indian dance elements with contemporary Bollywood choreography.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(19, 86, 'Hindu Society of Minnesota', 'Arts & Culture', 'Community organization that often hosts Indian cultural events and may offer dance programs as part of their cultural preservation and education activities.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(20, 86, 'India Cultural Center Minneapolis', 'Community Development', 'Cultural center dedicated to promoting Indian arts, including dance, music, and cultural education programs for the Minnesota Indian community.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(21, 86, 'SEWA-AIFW (Asian Indian Family Wellness)', 'Health', 'Non-profit organization committed to serving, supporting, and enhancing family wellness for the South Asian community, especially the vulnerable and underserved, in the Twin Cities. Provides healthcare access, wellness information, domestic violence support, and care for seniors.', 'https://www.sewa-aifw.org/', 'info@sewa-aifw.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(22, 86, 'School of India for Languages and Culture (SILC)', 'Education', 'Established in 1979 to promote community for those whose family or culture includes India. Mission is to promote deeper understanding of India\'s rich diversity, history, culture, natural resources, festivals, games, and food through language and cultural education programs.', 'https://www.silcmn.org/', 'info@silcmn.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(23, 86, 'Camp Masala', 'Education', 'Two-day residential program for children adopted from India and South Asian heritage youth. Seeks to foster an environment for participants to develop lasting relationships and explore their shared South Asian heritage through fun and educational activities with authentic community perspectives.', 'https://www.campmasala.org/', 'info@campmasala.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(24, 86, 'Kalavandanam School of Dance', 'Arts & Culture', 'Indian classical dance school specializing in Bharatanatyam and other South Indian dance forms. Provides comprehensive training in classical Indian dance traditions with focus on cultural preservation and artistic excellence.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(26, 86, 'Minnesota India Professional Network', 'Community Development', 'Professional development and networking organization supporting Indian professionals in Minnesota through mentorship, career development, and community building initiatives.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(27, 86, 'Indian Student Association - University of Minnesota', 'Education', 'Student organization at the University of Minnesota dedicated to promoting Indian culture, providing support for international students from India, and organizing cultural events and educational programs.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(28, 86, 'Bharatiya Senior Citizens of Minnesota', 'Senior Services', 'Organization focused on providing support, social activities, and health education for elderly members of the Indian community in Minnesota.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(29, 86, 'Asha for Education - Twin Cities Chapter', 'Education', 'Volunteer organization focused on providing education to underprivileged children in India. Works to ensure quality basic education for all children and supports grassroots educational initiatives in rural and urban India.', 'https://www.ashanet.org/twincities/', 'twincities@ashanet.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(30, 86, 'AKSHAYA PATRA - Minnesota Supporters', 'Hunger Relief', 'Supports the world\'s largest school meal program in India. Minnesota-based supporters help provide nutritious school meals to children across India, combining hunger relief with education support.', 'https://www.akshayapatrausa.org/', 'info@akshayapatrausa.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(31, 86, 'CRY America - Minnesota Chapter', 'Youth Services', 'Child Rights and You (CRY) Minnesota chapter works to ensure happier childhoods for underprivileged children in India. Focuses on education, healthcare, protection from exploitation, and participation in decisions affecting children.', 'https://www.cryamerica.org/', 'info@cryamerica.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(32, 86, 'Seva Foundation - Minnesota Chapter', 'Health', 'International health organization working to eliminate avoidable blindness and restore sight in India and other developing countries. Minnesota supporters help fund eye care programs and community health initiatives.', 'https://www.seva.org/', 'info@seva.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(33, 86, 'American India Foundation - Minnesota Supporters', 'Community Development', 'Works to accelerate social and economic change in India through innovation, collaboration and investment in extraordinary talent and teams. Minnesota supporters help fund education, healthcare, and livelihood programs.', 'https://www.aif.org/', 'info@aif.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(34, 86, 'India Development Relief Fund - Minnesota Chapter', 'Community Development', 'Promotes sustainable development in India through funding of education, rural development, and disaster relief programs. Minnesota chapter organizes fundraising and awareness activities for development projects in India.', 'https://www.idrf.org/', 'info@idrf.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(35, 86, 'Sadhana Center for Management and Leadership Development', 'Education', 'Organization focused on leadership development and management training with connections to Indian educational methodologies and community development approaches.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(36, 86, 'TiE Minnesota (The Indus Entrepreneurs)', 'Community Development', 'Non-profit organization dedicated to fostering entrepreneurship and supporting entrepreneurs, with strong connections to the Indian business community. Provides mentoring, networking, and educational programs.', 'https://minnesota.tie.org/', 'info@minnesota.tie.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(37, 86, 'Minnesota Friends of India Relief', 'Community Development', 'Community organization that mobilizes support for disaster relief and emergency aid in India. Coordinates fundraising efforts during natural disasters and humanitarian crises affecting India.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(38, 86, 'IMSOM (Indian Musical Society of MN)', 'Health', 'Professional organization of Indian physicians and medical professionals in Minnesota. Provides medical support to the community, organizes health awareness programs, and supports medical missions to India and local healthcare initiatives.', 'https://www.imsom.org/', 'info@imsom.org', 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(39, 86, 'Association of Physicians of Pakistani Descent of Minnesota', 'Health', 'Professional medical organization serving South Asian physicians and providing healthcare support to the broader South Asian community in Minnesota.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(40, 86, 'South Asian Women\'s Network Minnesota', 'Community Development', 'Support network dedicated to empowering South Asian women in Minnesota through advocacy, education, and community building. Addresses issues affecting South Asian women including domestic violence, mental health, and economic empowerment.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(41, 86, 'SAATH (South Asian Alliance for Advocacy, Training & Healing)', 'Community Development', 'Organization focused on building community among South Asians through advocacy, education, and healing. Provides culturally competent support services and works to address social justice issues affecting the South Asian community.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(42, 86, 'Mixed Blood Theatre - South Asian Programming', 'Arts & Culture', 'While not exclusively Indian, Mixed Blood Theatre in Minneapolis regularly features South Asian artists and stories, promoting diverse voices including Indian and South Asian theatrical works and artists in Minnesota.', 'https://mixedblood.com/', 'info@mixedblood.com', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(43, 86, 'Pangea World Theater - South Asian Arts', 'Arts & Culture', 'Multicultural theater organization in Minneapolis that regularly features South Asian stories, artists, and cultural programming as part of their mission to amplify diverse voices.', 'https://www.pangeaworldtheater.org/', 'info@pangeaworldtheater.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(44, 86, 'Theater Mu - Asian American Theater', 'Arts & Culture', 'While broader Asian focus, Theater Mu in Minneapolis includes South Asian and Indian theatrical works and artists as part of their mission to create theater by and for Asian Pacific American communities.', 'https://www.theatermu.org/', 'info@theatermu.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(45, 86, 'Minnesota Council of Hindu Temples', 'Arts & Culture', 'Umbrella organization coordinating activities among various Hindu temples and cultural organizations in Minnesota. Promotes Hindu dharma, culture, and community service activities.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(46, 86, 'Indo-American Association of Minnesota', 'Community Development', 'Community organization providing support, networking, and cultural programming for Indian Americans in Minnesota. Focuses on integration, cultural preservation, and community building activities.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(47, 86, 'Minnesota Friends of India Education', 'Education', 'Organization supporting educational initiatives in India through fundraising, volunteer programs, and partnerships with schools and educational institutions in India.', NULL, NULL, 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(48, 86, 'IMSOM (Indian Medical Society of Minnesota)', 'Health', 'Professional organization of Indian physicians and medical professionals practicing in Minnesota. Provides medical outreach to the community, organizes health awareness programs, and supports medical missions and healthcare initiatives both locally and in India.', '', NULL, 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(49, 86, 'SAATH Minnesota', 'Community Development', 'South Asian community organization focused on building connections, providing support services, and addressing social issues affecting the South Asian diaspora in Minnesota through advocacy and community programs.', 'https://www.saathmn.org/', 'info@saathmn.org', 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(50, 86, 'South Asian Women\'s Network Minnesota', 'Community Development', 'Support network dedicated to empowering South Asian women through advocacy, education, professional development, and community building. Addresses domestic violence, mental health, career advancement, and cultural integration issues.', 'https://www.sawnmn.org/', NULL, 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(51, 86, 'Hindu Society of Minnesota', 'Arts & Culture', 'Largest Hindu temple in North America providing religious, spiritual, educational, social, and cultural activities for all generations of the Hindu community. Offers community resources and cultural programming.', 'https://www.hindutemplemn.org/', 'info@hindutemplemn.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(52, 86, 'Jain Center of Minnesota', 'Arts & Culture', 'Charitable non-profit organization dedicated to following and seeking better understanding of Jain religion\'s doctrine and beliefs. Based in Twin Cities, formed in October 1989, serves the Jain community in Minnesota.', 'https://jaincentermn.org/', 'info@jaincentermn.org', 'pending', NULL, '2025-08-30', '2025-08-30', NULL),
(53, 86, 'BAPS Shri Swaminarayan Mandir - Minneapolis', 'Arts & Culture', 'Hindu temple and cultural center serving the Swaminarayan Hindu community in Minnesota. Provides religious services, cultural programs, and community activities rooted in Hindu traditions and values.', 'https://www.baps.org/Global-Network/North-America/Minneapolis.aspx', NULL, 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(54, 86, 'Geeta Ashram Minnesota', 'Arts & Culture', 'Spiritual and cultural organization focused on Hindu philosophy, meditation, and spiritual education. Provides classes on Hindu scriptures, yoga, and spiritual practices for the Minnesota community.', 'https://gitaashrammn.org/', NULL, 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(55, 86, 'SV Hindu Temple', 'Arts & Culture', 'Hindu temple serving the spiritual and cultural needs of the South Indian community in Minnesota, with focus on South Indian traditions, festivals, and religious practices.', 'https://svtemplemn.org/', NULL, 'pending', NULL, '2025-08-30', '2025-09-07', NULL),
(56, 86, 'Minnesota Indian Classical Music Society', 'Arts & Culture', 'Organization dedicated to promoting and preserving Indian classical music traditions in Minnesota through concerts, classes, and cultural events featuring renowned Indian classical musicians.', 'testing2', 'testing3', 'pending', NULL, '2025-08-30', '2025-09-05', NULL),
(57, 86, 'Nrityagram Minnesota', 'Arts & Culture', 'Dance and theater organization focused on Indian classical and contemporary performances, offering training and staging productions that showcase Indian theatrical and dance traditions.', 'testing', 'testing@email', 'pending', NULL, '2025-08-30', '2025-09-05', NULL),
(61, 86, 'KEATS', 'Education', 'KEATS USA dedicates itself to improve the society by taking up activities in the areas of Education, Empowerment and Environment.', 'https://www.keatsusa.com/', 'keatsusainc@gmail.com', 'pending', NULL, NULL, NULL, NULL);
